INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(8544, 'plPL', 'Naramienniki zdobywcy', 'Mówi się wśród nas, że zdobne naramienniki noszone przez śmiertelne rasy zrodziły się z prób naśladowania skrzydeł smoka.$B$BPrzynieś mi więzy noszone przez najwyższych przywódców Qiraji, a ukształtuję z nich naramienniki straszliwsze nawet niż skrzydła samego Nefariana!', 'Przynieś więzy dowodzenia Qiraji, 2 idole nocy, 5 kamiennych skarabeuszy i 5 glinianych skarabeuszy Andorgos w Ahn\'Qiraj. Aby ukończyć to zadanie, musisz też zdobyć u Miotu Nozdormu reputację na poziomie Neutralny.', '', 'Wróć do Andorgos w Ahn\'Qiraj.', '', '', '', '', 0),
(8559, 'plPL', 'Nagolenniki zdobywcy', 'Magia Qiraji jest potężna i pradawna. Najpotężniejsi Qiraji władają przedmiotami o takiej mocy, że nawet smok by się zawahał.$B$BPrzynieś mi więzy dowodzenia Qiraji i inne drobne składniki, a wykonam dla ciebie parę potężnych butów.$B$BPrzydadzą ci się w walce z wrogiem.', 'Przynieś więzy dowodzenia Qiraji, 2 idole wojny, 5 skarabeuszy z kości słoniowej i 5 złotych skarabeuszy Kandrostraszowi w Ahn\'Qiraj. Aby ukończyć to zadanie, musisz też zdobyć u Miotu Nozdormu reputację na poziomie Neutralny.', '', 'Wróć do Kandrostrasza w Ahn\'Qiraj.', '', '', '', '', 0),
(8560, 'plPL', 'Osłony nóg zdobywcy', 'Chcesz dowieść swojej wartości mojemu rodowi, śmiertelniku? Dobrze więc, może zdołamy sobie nawzajem pomóc.$B$BPradawny czerw piaskowy Ouro to istota o legendarnej mocy. Podobno stworzył go sam Przedwieczny jako szyderstwo z życia.$B$BJego skóra jest nienaturalna... gruba, niemal nie do przebicia, a mimo to elastyczna, dzięki czemu porusza się z szybkością i gracją znacznie mniejszego stworzenia.$B$BPrzynieś mi próbkę jego skóry wraz z innymi drobnymi składnikami, a wykonam dla ciebie nogawice o wielkiej mocy.', 'Przynieś nienaruszoną skórę Ouro, 2 idole śmierci, 5 brązowych skarabeuszy i 5 skarabeuszy z kości słoniowej Kandrostraszowi w Ahn\'Qiraj. Aby ukończyć to zadanie, musisz też zdobyć u Miotu Nozdormu reputację na poziomie Przyjazny.', '', 'Wróć do Kandrostrasza w Ahn\'Qiraj.', '', '', '', '', 0),
(8561, 'plPL', 'Korona zdobywcy', 'Bliźniaczy Cesarze... ich nieustanne szepty powoli odbierają mi zdrowe zmysły. Drwią ze mnie, bo wiedzą, że nie mogę zapuścić się dalej w ich domenę, by ocalić mojego brata Arygosa.$B$BW wizjach widzę ich potworne oblicza zdobne w potężne korony. Ale zemszczę się... Przemienię te symbole potęgi Qiraji w takie, które lepiej posłużą naszym potrzebom.$B$BPrzynieś mi potrzebne składniki, $N. Dam ci nakrycie głowy o niezrównanej mocy.', 'Przynieś diadem Vek\'nilasha, 2 idole słońca, 5 kamiennych skarabeuszy i 5 kryształowych skarabeuszy Andorgos w Ahn\'Qiraj. Aby ukończyć to zadanie, musisz też zdobyć u Miotu Nozdormu reputację na poziomie Przyjazny.', '', 'Wróć do Andorgos w Ahn\'Qiraj.', '', '', '', '', 0),
(8562, 'plPL', 'Napierśnik zdobywcy', 'Przedwieczny, którego imienia lepiej nie wymawiać, powoli budzi się ze snu pod Ahn\'Qiraj. Straszny los, który czeka Azeroth, może nadejść za kilka dni albo za kilka lat – czas nie ma znaczenia dla istot o jego mocy.$B$BGdy gwiazdy będą mu sprzyjać, uderzy ze straszliwym gniewem na wszystkie żywe istoty. Musisz go odnaleźć wcześniej i znaleźć sposób, by położyć kres jego istnieniu.$B$BDokonaj tego i przynieś mi kawałek jego skorupy. Dam ci zbroję, jakiej nie nosił żaden śmiertelnik... zbroję godną kogoś, kto zabił boga!', 'Przynieś karapaks Przedwiecznego, 2 idole wojny, 5 srebrnych skarabeuszy i 5 kościanych skarabeuszy Vethserze w Ahn\'Qiraj. Aby ukończyć to zadanie, musisz też zdobyć u Miotu Nozdormu reputację na poziomie Szanowany.', '', 'Wróć do Vethsery w Ahn\'Qiraj.', '', '', '', '', 0),
(8579, 'plPL', 'Śmiertelni czempioni', '', '', '', 'Wróć do Kandrostrasza.', '', '', '', '', 0),
