INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(15263, 0, 1, 'plPL', 'Kulcie się, śmiertelnicy! Nadchodzi era ciemności.'),
(15263, 0, 2, 'plPL', 'Drżyjcie! Nadszedł wasz koniec.'),
(15263, 1, 1, 'plPL', 'Tchórzliwe nędzne kreatury! Utoniecie w rzekach krwi!'),
(15263, 1, 2, 'plPL', 'Krzyki umierających wypełnią powietrze. Symfonia grozy zaraz się rozpocznie!'),
(15263, 2, 0, 'plPL', 'Szykujcie się na powrót pradawnych!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(10755, 'plPL', '%s wydaje dziwny dźwięk.', '', 0),
(10901, 'plPL', 'Niech poczują gniew Błękitnego Stada! Niech Malygos mnie chroni!', '', 0),
(10903, 'plPL', '', 'Poddajcie się niekończącemu się snowi, maleństwa. Niech was pochłonie!', 0),
(10904, 'plPL', 'Anachronosie, ta dywersja da tobie i młodemu druidowi dość czasu, by zapieczętować wrota. Nie zawahaj się. A teraz zobaczmy, jak poradzą sobie z magią chaosu.', '', 0),
(10908, 'plPL', '', 'Odepchniemy ich, Anachronosie. Przysięgam. Ty wypełnij swoją część zadania. Niech twoje ręce nie zadrżą, gdy będziesz pieczętować nasz los za barierą.', 0),
(10911, 'plPL', '', 'Jest pewien sposób...', 0),
(10912, 'plPL', '', '%s spogląda na swoich towarzyszy.', 0),
(10913, 'plPL', '%s kiwa głową ze zrozumieniem.', '', 0),
(11061, 'plPL', '', 'Stąpaj ostrożnie, śmiertelniku. Kroczysz tam, gdzie swój kres znalazły istoty potężniejsze od ciebie.', 0),
(11062, 'plPL', 'Tysiąc lat temu, gdy dobiegła końca Wojna Ruchomych Piasków, troje naszych pobratymców poświęciło się i powstrzymywało Qiraji w tych komnatach, podczas gdy Anachronos i Jeleniorogi zamykali Ahn\'Qiraj.$B$BKażde z nas przysięgło, że odszuka Merithrę, Arygosa i Caelestrasza, jeśli Mur Skarabeusza kiedykolwiek runie.$B$BI runął... więc przybyliśmy.', '', 0),
(11081, 'plPL', '', 'Mieszka tu niewypowiedziana groza, śmiertelniku. C\'Thun i jego wyznawcy to nie tylko obraza natury – ich istnienie zapowiada zagładę Azeroth, jakie znamy.$B$BMerithra poświęciła się tysiąc lat temu wraz z Caelestraszem i Arygosem, bo i oni to wiedzieli. Jesteśmy tu, bo przysięgliśmy po nich wrócić, ale też dlatego, że C\'Thun musi zostać powstrzymany!', 0),
(11115, 'plPL', '%s zostaje pożarty!', '%s zostaje pożarty!', 0),
(11343, 'plPL', '%s zaczyna zwalniać!', '', 0),
(11345, 'plPL', '%s zamarza!', '', 0),
(11346, 'plPL', '%s zaczyna pękać!', '', 0),
(11347, 'plPL', '%s zaraz się roztrzaska!', '', 0),
(11353, 'plPL', '', 'Bohaterowie Miotu? C\'Thun musi zostać wygnany! Możemy ci pomóc, śmiertelniku!', 0),
(11354, 'plPL', 'Na moich oczach dzieje się cud! Przez tysiąc lat niewoli żaden ŻYWY okaz – poza tymi plugawymi Qiraji i silithidami – nie wkroczył do tych komnat.', '', 0),
(11390, 'plPL', 'Świat ma dług wdzięczności wobec ciebie i twoich sprzymierzeńców, $n.', '', 0),
(11392, 'plPL', '', 'Wszyscy dowiedzą się, co wydarzyło się w tej przeklętej świątyni, $gbohaterze:bohaterko;. Zapiszą to w księgach historii – opowieści o tym będą krążyć jako legenda od Azeroth po najdalsze krańce samej Otchłani!', 0),
(11442, 'plPL', 'Zostaniecie osądzeni za zbezczeszczenie tej świętej ziemi! Nikt nie podważy praw Pradawnych! Intruzi zostaną unicestwieni!\n', '', 0),
(11443, 'plPL', 'Skazuję cię na śmierć!', '', 0),
(11444, 'plPL', 'Służę do samego końca!', '', 0),
(11445, 'plPL', 'Tak bardzo spieszno ci umrzeć? Z radością spełnię twoje życzenie...', '', 0),
(11446, 'plPL', 'Niech twoja śmierć będzie przykładem!', '', 0),
(11447, 'plPL', 'Tylko odwlekacie nieuniknione!', '', 0),
(11452, 'plPL', 'Mój bracie, nie!', '', 0),
(11453, 'plPL', 'Nie umkniesz śmierci!', '', 0),
(11454, 'plPL', 'Vek\'lorze, czuję twój ból!', '', 0),
(11455, 'plPL', 'Twój los jest przesądzony!', '', 0),
(11476, 'plPL', '%s słabnie!', '', 0),
(11692, 'plPL', '%s dzieli się swoją mocą z pobratymcami.', '%s dzieli się swoją mocą z pobratymcami.', 0),
(11695, 'plPL', '%s całkowicie zamarza!', '', 0),
(11700, 'plPL', 'Ogromna gałka oczna unosząca się na środku komnaty kieruje na ciebie wzrok. Stoisz przed bogiem.', '', 0),
(11702, 'plPL', 'Tylko ciało i kości. Śmiertelnicy to tak łatwa zdobycz...', '', 0),
(11706, 'plPL', 'Gdzie twoje maniery, bracie? Powitajmy należycie naszych gości.', '', 0),
(11707, 'plPL', 'Będzie ból...', '', 0),
(11708, 'plPL', 'Och, tyle bólu...', '', 0),
(11709, 'plPL', 'Chodźcie, maleństwa.\n', '', 0),
(11710, 'plPL', 'Uczta dusz zaczyna się teraz...', '', 0),
(12848, 'plPL', '', 'Po śmierci Cesarzy magiczna ochrona blokująca teleportację wewnątrz świątyni znacznie osłabła. Jeśli chcesz, mogę przenieść cię do leża Cesarzy.', 0),
(12849, 'plPL', 'Teleportuj mnie, proszę, do leża Bliźniaczych Cesarzy.', 'Teleportuj mnie, proszę, do leża Bliźniaczych Cesarzy.', 0),
(12850, 'plPL', '', 'Skoro Ouro nie żyje, droga do ostatniej komnaty stoi otworem. Jeśli chcesz, mogę cię tam przenieść.', 0),
(12851, 'plPL', 'Proszę, teleportuj mnie do ostatniej komnaty.', 'Proszę, teleportuj mnie do ostatniej komnaty.', 0);
